 "content": "from collections import deque


def transform(grid):
    """Fill interiors of outlined rectangular frames with the color of the small solid marker."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The marker is the smallest non-background connected component, not touching an outline.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    # All framed shapes are hollow rectangles; the marker is a solid miniature glyph,
    # identified as a non-frame component. Choose its color by the smallest component.
    frames = []
    for color, cells in comps:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        if len(cells) >= 8 and len({r for r,c in cells}) >= 2 and len({c for r,c in cells}) >= 2:
            if all((r,c) in set(cells) for r in range(r0,r1+1) for c in (c0,c1)) and all((r,c) in set(cells) for c in range(c0,c1+1) for r in (r0,r1)):
                frames.append((color,r0,r1,c0,c1))
    frame_colors = {f[0] for f in frames}
    marker = [(color,cells) for color,cells in comps if color not in frame_colors]
    fill_color = min(marker, key=lambda x: len(x[1]))[0] if marker else next((c for c in set(v for row in grid for v in row) if c != bg and c not in frame_colors), bg)
    for color,r0,r1,c0,c1 in frames:
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if grid[r][c] == bg:
                    out[r][c] = fill_color
    return out


def _demo_check():
    # Compact checks of the demonstrated rule: border color remains, enclosed area is filled.
    g = [[8,8,8,8,8],[8,5,5,5,8],[8,5,8,5,8],[8,5,5,5,8],[8,8,8,8,8]]
    assert transform(g)[2][2] == 5
    return True

if __name__ == '__main__':
    assert _demo_check()
    print('demo check passed')
    # test input is supplied by the ARC runner, not this standalone module.
    print('transform ready')
