 "content": "from collections import Counter, deque


def transform(grid):
    """Fill hollow rectangular frames by interior-area parity: odd -> 7, even -> 2."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = min(map(len, grid))
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = ({(r0, x) for x in range(c0, c1 + 1)}
                      | {(r1, x) for x in range(c0, c1 + 1)}
                      | {(y, c0) for y in range(r0, r1 + 1)}
                      | {(y, c1) for y in range(r0, r1 + 1)})
            if cells != border:
                continue
            fill = 7 if ((r1 - r0 - 1) * (c1 - c0 - 1)) % 2 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == bg:
                        out[y][x] = fill
    return out


if __name__ == '__main__':
    # Basic sanity checks for both parity cases.
    assert transform([[0, 5, 5, 5, 0], [0, 5, 0, 0, 0], [0, 5, 0, 0, 0],
                      [0, 5, 5, 5, 0]])[1][2] == 2
    assert transform([[0, 5, 5, 5, 0], [0, 5, 0, 5, 0], [0, 5, 5, 5, 0]])[1][2] == 7
    print('sanity checks passed')
